from fractions import Fraction as Fr
from decimal import Decimal, ROUND_HALF_UP
import math, datetime

def dec(x): return Decimal(repr(x)) if isinstance(x,float) else Decimal(x)

def compute(cutoff, budget, programs, rates, ledger):
    """programs: list of (id,name,w,max,appr,tie); rates: dict; ledger rows tuples A..H (None for blank)"""
    sel = {}
    for r in ledger:
        if r[0] in (None, ""): continue
        a,b,c,d,e,f,g,h = r
        if d <= cutoff:
            k=(a,b)
            if k not in sel or c > sel[k][2]: sel[k]=r
    elig = {p[0]:0 for p in programs}
    for k,r in sel.items():
        a,b,c,d,e,f,g,h = r
        if f=='posted' and e<=cutoff:
            usd = dec(h)*dec(rates[g])*100
            elig[a] += int(usd.quantize(Decimal(1), rounding=ROUND_HALF_UP))
    caps={}
    for p in programs:
        pid,name,w,mx,appr,tie=p
        mc=int((dec(mx)*100).quantize(Decimal(1),rounding=ROUND_HALF_UP))
        caps[pid]= max(0,min(mc,elig[pid])) if appr=='approved' else 0
    bc=int((dec(budget)*100).quantize(Decimal(1),rounding=ROUND_HALF_UP))
    S=sum(caps.values()); T=min(bc,S)
    ids=[p[0] for p in programs]; W={p[0]:p[2] for p in programs}; tie={p[0]:p[5] for p in programs}
    q={}
    if T==0: q={i:Fr(0) for i in ids}
    elif T==S: q={i:Fr(caps[i]) for i in ids}
    else:
        active=set(ids); fixed=0
        while True:
            lam=Fr(T-fixed, sum(W[i] for i in active))
            newcap=[i for i in active if caps[i] <= lam*W[i]]
            if not newcap: break
            for i in newcap: active.remove(i); fixed+=caps[i]; q[i]=Fr(caps[i])
        for i in active: q[i]=lam*W[i]
    fl={i:math.floor(q[i]) for i in ids}
    R=T-sum(fl.values())
    order=sorted(ids,key=lambda i:(-(q[i]-fl[i]), tie[i]))
    aw=dict(fl)
    for i in order[:R]: aw[i]+=1
    assert sum(aw.values())==T and all(0<=aw[i]<=caps[i] for i in ids)
    return {i:(elig[i],caps[i],q[i],aw[i]) for i in ids}, T, bc

def from_wb(path):
    import openpyxl
    wb=openpyxl.load_workbook(path,data_only=True)
    c=wb['Control']; cutoff=c['B2'].value; budget=c['B3'].value
    progs=[tuple(cell.value for cell in row) for row in wb['Programs'].iter_rows(min_row=2,max_row=9)]
    rates={r[0].value:r[1].value for r in wb['Rates'].iter_rows(min_row=2,max_row=4)}
    led=[tuple(cell.value for cell in row[:8]) for row in wb['Ledger'].iter_rows(min_row=2,max_row=501)]
    return compute(cutoff,budget,progs,rates,led)

if __name__=='__main__':
    import sys
    res,T,bc=from_wb(sys.argv[1])
    for k,v in res.items(): print(k, v[0]/100, v[1]/100, float(v[2])/100, v[3]/100)
    print('T',T,'budget',bc,'sum',sum(v[3] for v in res.values()))
